  const a = (rgba & 0xff000000) >>> 24,
        r = (rgba & 0x00ff0000) >>> 16,
        g = (rgba & 0x0000ff00) >>> 8,
        b = rgba & 0x000000ff;
  return [r, g, b, a];
}; // https://stackoverflow.com/a/54030756/3994249

